-- ST Planning v017 — Batch Capacity Baseline
-- 1. Enable masking/unmasking/support route steps for internal finite-capacity batching.
UPDATE config_items
SET data = data || '{"scheduleEnabled":true,"batchEnabled":true,"seedVersion":"v017","assumptionBaseline":true}'::jsonb, updated_at=now()
WHERE category='MAIN_OPERATION' AND code = ANY(ARRAY['MASKING','UNMASKING','NDT','ST_INSPECTION','ST_FINAL','REWORK']);

UPDATE config_rules
SET action_json = action_json || '{"maxJobs":20,"maxQty":1000,"maxSurfaceDm2":10000}'::jsonb,
    notes='v017 global safety fallback: 20 jobs / 1000 pcs / 10000 dm2. Lower-priority-number Main Operation rules override.', updated_at=now()
WHERE rule_type='BATCH' AND code='DEFAULT_BATCH';

ON CONFLICT (rule_type,code) DO UPDATE SET name=EXCLUDED.name,enabled=true,priority=EXCLUDED.priority,condition_json=EXCLUDED.condition_json,action_json=EXCLUDED.action_json,notes=EXCLUDED.notes,updated_at=now();
